import { addMotion, openBox } from './log-copy-motion.js';

// 1.0.1(11-04) 컨셉 30 은 틀이 가진 그림 부품이 직접 움직이고 눌려요 — live(조각, { anim, origin, vars, egg }): 첫 태그에 움직임(공용 bl- 키프레임) · 축 · 변수 · 누르면 반응(data-bl-egg)
const live = (html, { anim = '', origin = '', vars = '', egg = '' } = {}) => {
    let out = html.replace(/ style="([^"]*)"/, (_, st) => ` style="${st}${origin ? `;transform-origin:${origin}` : ''}${vars ? `;${vars}` : ''}${anim ? `;animation:${anim}` : ''}"`);
    if (egg) out = mark(out, `data-bl-egg="${egg}"`);
    return out;
};

// 그림 안 둥근 첫 글자(영화 자막 배지) — src/log-copy-presets.js 와 같은 정의
const initial = name => [...String(name ?? '')].find(ch => /[\p{L}\p{N}]/u.test(ch)) ?? '';

