// ── 컨셉 30종 모양 조각 (1.0.1 · 시안 frames-1103/G-*.dc.html) — (k, p, ui) → HTML. p 는 drawConcept 의 부품(head · body · info · tail · title() · date() · pills() · f() · tailText · n · model · fields)
// 시안의 기울기(tilt)는 넣지 않아요(붙여 넣은 곳에서 깨져요). 고정 폭 없이 max-width 만 — 폰 폭(360px)에서도 접혀요. 글꼴은 테마 화면 글꼴(ui) 그대로, 이모지는 시안에 있는 것만.
const caps = (text, color, ui, size = 11, more = {}) => tag('span', { color, ...font(ui, size, '650'), 'letter-spacing': '0.14em', 'line-height': '1.5', 'white-space': 'nowrap', overflow: 'hidden', 'text-overflow': 'ellipsis', 'min-width': '0', ...more }, esc(text));
const row = (inner, more = {}) => tag('div', { display: 'flex', 'align-items': 'center', gap: '8px', 'min-width': '0', ...more }, inner);
const spacer = tag('span', { flex: '1 1 auto' }, '');
const between = (left, right, more = {}) => row(left + spacer + right, more);
const ruleLine = (style, color, more = {}) => tag('span', { flex: '1 1 auto', 'min-width': '8px', height: '0', 'border-top': `1px ${style} ${color}`, ...more }, '');
/** 이름 줄: 이름(제목) — 선 — 날짜 */
const nameLine = (k, ui, p, style = 'solid', color = k.line, left = '', right = '') => row(left + p.title({ flex: '0 1 auto' }) + ruleLine(style, color) + p.date() + right);
const small = (html, color, ui, more = {}) => tag('div', { color, ...font(ui, 11), 'line-height': '1.5', 'overflow-wrap': 'anywhere', 'min-width': '0', ...more }, html);
/** 바닥 줄: 왼쪽 꼬리 글 · 오른쪽 개수 */
const tailRow = (k, ui, p, left, color = k.faceMuted, more = {}) => between(small(left, color, ui, { flex: '1 1 auto' }), small(esc(p.count), color, ui, { flex: '0 0 auto' }), { 'margin-top': '10px', ...more });
/** 라벨 : 값 두 칸 표 (수사 파일 · 여권 · 택배 송장) */
const grid2 = (k, ui, rows, color, valueColor, lineColor) => rows.filter(([, v]) => v).map(([label, v]) => row(caps(label, color, ui, 10, { flex: '0 0 64px' }) + tag('span', { flex: '1 1 auto', 'min-width': '0', color: valueColor, ...font(ui, 12, '650'), 'line-height': '1.6', 'border-bottom': `1px solid ${lineColor}`, 'overflow-wrap': 'anywhere' }, v), { 'align-items': 'baseline', margin: '0 0 4px' })).join('');
const bodyBox = (k, p, more = {}) => tag('div', { ...box, 'border-radius': '12px', overflow: 'hidden', ...more }, p.body);

